SELECT COUNT(*) FROM (SELECT "ANNOTATIONS_BOOK"."ID" AS "COL1" FROM "ANNOTATIONS_BOOK" GROUP BY "ANNOTATIONS_BOOK"."ID" HAVING SUM("ANNOTATIONS_BOOK"."RATING") = (SUM("ANNOTATIONS_BOOK"."RATING"))) subquery;
SELECT (42) AS "RANDOM_VALUE", "ANNOTATIONS_EMPLOYEE"."ID", "ANNOTATIONS_EMPLOYEE"."FIRST_NAME", "ANNOTATIONS_EMPLOYEE"."MANAGER", "ANNOTATIONS_EMPLOYEE"."LAST_NAME", "ANNOTATIONS_EMPLOYEE"."STORE_ID", "ANNOTATIONS_EMPLOYEE"."AGE", "ANNOTATIONS_EMPLOYEE"."SALARY", CAST(%s AS INTEGER) AS "ANNOTATED_VALUE", "ANNOTATIONS_STORE"."ID", "ANNOTATIONS_STORE"."NAME", "ANNOTATIONS_STORE"."ORIGINAL_OPENING", "ANNOTATIONS_STORE"."FRIDAY_NIGHT_CLOSING", "ANNOTATIONS_STORE"."SURFACE" FROM "ANNOTATIONS_EMPLOYEE" INNER JOIN "ANNOTATIONS_STORE" ON ("ANNOTATIONS_EMPLOYEE"."STORE_ID" = "ANNOTATIONS_STORE"."ID") ORDER BY "ANNOTATIONS_EMPLOYEE"."ID" ASC;
SELECT (42) AS "RANDOM_VALUE", "ANNOTATIONS_EMPLOYEE"."ID", "ANNOTATIONS_EMPLOYEE"."FIRST_NAME", "ANNOTATIONS_EMPLOYEE"."MANAGER", "ANNOTATIONS_EMPLOYEE"."LAST_NAME", "ANNOTATIONS_EMPLOYEE"."STORE_ID", "ANNOTATIONS_EMPLOYEE"."SALARY", CAST(%s AS INTEGER) AS "ANNOTATED_VALUE", "ANNOTATIONS_STORE"."ID", "ANNOTATIONS_STORE"."NAME", "ANNOTATIONS_STORE"."ORIGINAL_OPENING", "ANNOTATIONS_STORE"."FRIDAY_NIGHT_CLOSING", "ANNOTATIONS_STORE"."SURFACE" FROM "ANNOTATIONS_EMPLOYEE" INNER JOIN "ANNOTATIONS_STORE" ON ("ANNOTATIONS_EMPLOYEE"."STORE_ID" = "ANNOTATIONS_STORE"."ID") ORDER BY "ANNOTATIONS_EMPLOYEE"."ID" ASC;
SELECT ("ANNOTATIONS_BOOK"."PRICE" + CAST(%s AS INTEGER)) AS "NEW_PRICE" FROM "ANNOTATIONS_BOOK" WHERE ("ANNOTATIONS_BOOK"."PRICE" + CAST(%s AS INTEGER)) = CAST(%s AS DECIMAL(2, 0)) FETCH FIRST 21 ROWS ONLY;
SELECT ("ANNOTATIONS_BOOK"."RATING" - CAST(%s AS INTEGER)) AS "OTHER_RATING", "ANNOTATIONS_BOOK"."RATING" AS "RATING" FROM "ANNOTATIONS_BOOK" WHERE "ANNOTATIONS_BOOK"."ID" = %s FETCH FIRST 21 ROWS ONLY;
SELECT (case when name='Angus & Robinson' then chain else name end) AS "ANNOTATION" FROM "ANNOTATIONS_DEPARTMENTSTORE" INNER JOIN "ANNOTATIONS_STORE" ON ("ANNOTATIONS_DEPARTMENTSTORE"."STORE_PTR_ID" = "ANNOTATIONS_STORE"."ID");
SELECT (name) AS "ANNOTATION" FROM "ANNOTATIONS_DEPARTMENTSTORE" INNER JOIN "ANNOTATIONS_STORE" ON ("ANNOTATIONS_DEPARTMENTSTORE"."STORE_PTR_ID" = "ANNOTATIONS_STORE"."ID");
SELECT (surface) AS "ANNOTATION" FROM "ANNOTATIONS_DEPARTMENTSTORE" INNER JOIN "ANNOTATIONS_STORE" ON ("ANNOTATIONS_DEPARTMENTSTORE"."STORE_PTR_ID" = "ANNOTATIONS_STORE"."ID");
SELECT CAST(%s AS INTEGER) AS "A" FROM "ANNOTATIONS_AUTHOR" GROUP BY "ANNOTATIONS_AUTHOR"."ID", "ANNOTATIONS_AUTHOR"."NAME", "ANNOTATIONS_AUTHOR"."AGE" HAVING COUNT("ANNOTATIONS_AUTHOR"."ID") > %s FETCH FIRST 1 ROWS ONLY;
SELECT COUNT(*) AS "__COUNT" FROM "ANNOTATIONS_BOOK" WHERE "ANNOTATIONS_BOOK"."RATING" = ("ANNOTATIONS_BOOK"."RATING");
SELECT COUNT(*) AS "__COUNT" FROM "ANNOTATIONS_BOOK";
SELECT DISTINCT DATE(TRUNC_TIMESTAMP("ANNOTATIONS_BOOK"."PUBDATE", 'MONTH')) AS "DATEFIELD" FROM "ANNOTATIONS_BOOK" WHERE "ANNOTATIONS_BOOK"."PUBDATE" IS NOT NULL ORDER BY 1 ASC;
SELECT DISTINCT TRUNC_TIMESTAMP("ANNOTATIONS_STORE"."ORIGINAL_OPENING", 'YEAR') AS "DATETIMEFIELD" FROM "ANNOTATIONS_STORE" WHERE "ANNOTATIONS_STORE"."ORIGINAL_OPENING" IS NOT NULL ORDER BY 1 ASC;
SELECT MAX("ANNOTATIONS_BOOK"."PUBDATE") AS "MAX_PUBDATE" FROM "ANNOTATIONS_BOOK" GROUP BY "ANNOTATIONS_BOOK"."PUBLISHER_ID", ((SELECT (1) AS "A" FROM "ANNOTATIONS_BOOK_AUTHORS" U0 WHERE U0."BOOK_ID" = ("ANNOTATIONS_BOOK"."ID") FETCH FIRST 1 ROWS ONLY) IS NOT NULL) ORDER BY 1 ASC;
SELECT SUM(CAST(CAST(%s AS BOOLEAN) AS INTEGER)) AS "SELECTED__SUM" FROM "ANNOTATIONS_BOOK";
SELECT SUM("ANNOTATIONS_AUTHOR"."AGE") AS "AGE_SUM" FROM "ANNOTATIONS_AUTHOR";
SELECT SUM("ANNOTATIONS_AUTHOR"."AGE") AS "OTHERAGE_SUM" FROM "ANNOTATIONS_AUTHOR";
SELECT T3."NAME" AS "JACOB_NAME", T5."NAME" AS "JAMES_NAME" FROM "ANNOTATIONS_AUTHOR" INNER JOIN "ANNOTATIONS_AUTHOR_FRIENDS" ON ("ANNOTATIONS_AUTHOR"."ID" = "ANNOTATIONS_AUTHOR_FRIENDS"."FROM_AUTHOR_ID") INNER JOIN "ANNOTATIONS_AUTHOR" T3 ON ("ANNOTATIONS_AUTHOR_FRIENDS"."TO_AUTHOR_ID" = T3."ID") INNER JOIN "ANNOTATIONS_AUTHOR_FRIENDS" T4 ON ("ANNOTATIONS_AUTHOR"."ID" = T4."FROM_AUTHOR_ID") INNER JOIN "ANNOTATIONS_AUTHOR" T5 ON (T4."TO_AUTHOR_ID" = T5."ID") WHERE (T3."AGE" = %s AND "ANNOTATIONS_AUTHOR"."NAME" = %s AND T5."AGE" = %s);
SELECT YEAR("ANNOTATIONS_BOOK"."PUBDATE") AS "PUBDATE__YEAR", (SELECT U0."RATING" AS "RATING" FROM "ANNOTATIONS_BOOK" U0 WHERE YEAR(U0."PUBDATE") = (YEAR("ANNOTATIONS_BOOK"."PUBDATE")) ORDER BY 1 DESC FETCH FIRST 1 ROWS ONLY) AS "TOP_RATING_YEAR" FROM "ANNOTATIONS_BOOK";
SELECT YEAR("ANNOTATIONS_BOOK"."PUBDATE") AS "PUB_YEAR", SUM("ANNOTATIONS_BOOK"."PAGES") AS "TOTAL_PAGES", (SELECT U0."RATING" AS "RATING" FROM "ANNOTATIONS_BOOK" U0 WHERE YEAR(U0."PUBDATE") = (YEAR("ANNOTATIONS_BOOK"."PUBDATE")) ORDER BY 1 DESC FETCH FIRST 1 ROWS ONLY) AS "TOP_RATING" FROM "ANNOTATIONS_BOOK" GROUP BY YEAR("ANNOTATIONS_BOOK"."PUBDATE"), (SELECT U0."RATING" AS "RATING" FROM "ANNOTATIONS_BOOK" U0 WHERE YEAR(U0."PUBDATE") = (YEAR("ANNOTATIONS_BOOK"."PUBDATE")) ORDER BY 1 DESC FETCH FIRST 1 ROWS ONLY);
SELECT "ANNOTATIONS_AUTHOR"."AGE" AS "AGE" FROM "ANNOTATIONS_AUTHOR" GROUP BY "ANNOTATIONS_AUTHOR"."AGE" ORDER BY COUNT("ANNOTATIONS_AUTHOR"."AGE") ASC, 1 ASC FETCH FIRST 1 ROWS ONLY;
SELECT "ANNOTATIONS_AUTHOR"."AGE" AS "AGE" FROM "ANNOTATIONS_AUTHOR" GROUP BY "ANNOTATIONS_AUTHOR"."AGE" ORDER BY COUNT("ANNOTATIONS_AUTHOR"."AGE") ASC, 1 ASC;
SELECT "ANNOTATIONS_AUTHOR"."AGE" AS "AGE", COUNT("ANNOTATIONS_AUTHOR"."AGE") AS "AGE_COUNT" FROM "ANNOTATIONS_AUTHOR" GROUP BY "ANNOTATIONS_AUTHOR"."AGE" ORDER BY 2 ASC, 1 ASC;
SELECT "ANNOTATIONS_AUTHOR"."ID", "ANNOTATIONS_AUTHOR"."NAME", "ANNOTATIONS_AUTHOR"."AGE" FROM "ANNOTATIONS_AUTHOR" LEFT OUTER JOIN "ANNOTATIONS_BOOK_AUTHORS" ON ("ANNOTATIONS_AUTHOR"."ID" = "ANNOTATIONS_BOOK_AUTHORS"."AUTHOR_ID") LEFT OUTER JOIN "ANNOTATIONS_BOOK" ON ("ANNOTATIONS_BOOK_AUTHORS"."BOOK_ID" = "ANNOTATIONS_BOOK"."ID") GROUP BY "ANNOTATIONS_AUTHOR"."ID", "ANNOTATIONS_AUTHOR"."NAME", "ANNOTATIONS_AUTHOR"."AGE" HAVING SUM("ANNOTATIONS_BOOK"."PAGES") > %s ORDER BY "ANNOTATIONS_AUTHOR"."ID" ASC FETCH FIRST 1 ROWS ONLY;
SELECT "ANNOTATIONS_AUTHOR"."ID", "ANNOTATIONS_AUTHOR"."NAME", "ANNOTATIONS_AUTHOR"."AGE" FROM "ANNOTATIONS_AUTHOR" LEFT OUTER JOIN "ANNOTATIONS_BOOK_AUTHORS" ON ("ANNOTATIONS_AUTHOR"."ID" = "ANNOTATIONS_BOOK_AUTHORS"."AUTHOR_ID") LEFT OUTER JOIN "ANNOTATIONS_BOOK" ON ("ANNOTATIONS_BOOK_AUTHORS"."BOOK_ID" = "ANNOTATIONS_BOOK"."ID") GROUP BY "ANNOTATIONS_AUTHOR"."ID", "ANNOTATIONS_AUTHOR"."NAME", "ANNOTATIONS_AUTHOR"."AGE" HAVING SUM("ANNOTATIONS_BOOK"."PAGES") > %s;
SELECT "ANNOTATIONS_AUTHOR"."ID", "ANNOTATIONS_AUTHOR"."NAME", "ANNOTATIONS_AUTHOR"."AGE" FROM "ANNOTATIONS_AUTHOR" ORDER BY "ANNOTATIONS_AUTHOR"."AGE" ASC FETCH FIRST 1 ROWS ONLY;
SELECT "ANNOTATIONS_AUTHOR"."ID", "ANNOTATIONS_AUTHOR"."NAME", "ANNOTATIONS_AUTHOR"."AGE" FROM "ANNOTATIONS_AUTHOR" ORDER BY "ANNOTATIONS_AUTHOR"."AGE" ASC;
SELECT "ANNOTATIONS_AUTHOR"."ID", "ANNOTATIONS_AUTHOR"."NAME", "ANNOTATIONS_AUTHOR"."AGE", CAST(%s AS BOOLEAN) AS "EXISTS" FROM "ANNOTATIONS_AUTHOR" WHERE "ANNOTATIONS_AUTHOR"."ID" = %s FETCH FIRST 21 ROWS ONLY;
SELECT "ANNOTATIONS_AUTHOR"."ID", "ANNOTATIONS_AUTHOR"."NAME", "ANNOTATIONS_AUTHOR"."AGE", CAST(NULL AS BIGINT) AS "EMPTY" FROM "ANNOTATIONS_AUTHOR" ORDER BY "ANNOTATIONS_AUTHOR"."ID" ASC FETCH FIRST 1 ROWS ONLY;
SELECT "ANNOTATIONS_AUTHOR"."ID", "ANNOTATIONS_AUTHOR"."NAME", "ANNOTATIONS_AUTHOR"."AGE", "ANNOTATIONS_AUTHOR"."AGE" AS "OTHER_AGE" FROM "ANNOTATIONS_AUTHOR" ORDER BY 4 ASC;
SELECT "ANNOTATIONS_AUTHOR"."NAME" AS "NAME", CASE WHEN "ANNOTATIONS_BOOK"."ID" IS NULL THEN CAST(%s AS INTEGER) ELSE MAX(T4."PAGES") END AS "MAX_PAGES" FROM "ANNOTATIONS_AUTHOR" LEFT OUTER JOIN "ANNOTATIONS_BOOK" ON ("ANNOTATIONS_AUTHOR"."ID" = "ANNOTATIONS_BOOK"."CONTACT_ID") LEFT OUTER JOIN "ANNOTATIONS_BOOK_AUTHORS" ON ("ANNOTATIONS_AUTHOR"."ID" = "ANNOTATIONS_BOOK_AUTHORS"."AUTHOR_ID") LEFT OUTER JOIN "ANNOTATIONS_BOOK" T4 ON ("ANNOTATIONS_BOOK_AUTHORS"."BOOK_ID" = T4."ID") WHERE "ANNOTATIONS_AUTHOR"."AGE" < %s GROUP BY "ANNOTATIONS_AUTHOR"."ID", "ANNOTATIONS_AUTHOR"."NAME", "ANNOTATIONS_AUTHOR"."AGE", "ANNOTATIONS_BOOK"."ID";
SELECT "ANNOTATIONS_BOOK"."ID" AS "PK" FROM "ANNOTATIONS_BOOK" WHERE "ANNOTATIONS_BOOK"."ID" = %s FETCH FIRST 21 ROWS ONLY;
SELECT "ANNOTATIONS_BOOK"."ID" AS "PK", FLOOR("ANNOTATIONS_BOOK"."PRICE") AS "FLOOR_PRICE" FROM "ANNOTATIONS_BOOK";
SELECT "ANNOTATIONS_BOOK"."ID", "ANNOTATIONS_BOOK"."ISBN", "ANNOTATIONS_BOOK"."NAME", "ANNOTATIONS_BOOK"."PAGES", "ANNOTATIONS_BOOK"."PRICE", "ANNOTATIONS_BOOK"."CONTACT_ID", "ANNOTATIONS_BOOK"."PUBLISHER_ID", "ANNOTATIONS_BOOK"."PUBDATE", ("ANNOTATIONS_BOOK"."RATING" - CAST(%s AS INTEGER)) AS "OTHER_RATING" FROM "ANNOTATIONS_BOOK" WHERE ("ANNOTATIONS_BOOK"."RATING" - CAST(%s AS INTEGER)) = %s FETCH FIRST 21 ROWS ONLY;
