SELECT "ANNOTATIONS_BOOK"."ID", "ANNOTATIONS_BOOK"."ISBN", "ANNOTATIONS_BOOK"."NAME", "ANNOTATIONS_BOOK"."PAGES", "ANNOTATIONS_BOOK"."RATING", "ANNOTATIONS_BOOK"."PRICE", "ANNOTATIONS_BOOK"."CONTACT_ID", "ANNOTATIONS_BOOK"."PUBLISHER_ID", "ANNOTATIONS_BOOK"."PUBDATE" FROM "ANNOTATIONS_BOOK" ORDER BY "ANNOTATIONS_BOOK"."ID" ASC FETCH FIRST 1 ROWS ONLY;
SELECT "ANNOTATIONS_BOOK"."ID", "ANNOTATIONS_BOOK"."ISBN", "ANNOTATIONS_BOOK"."NAME", "ANNOTATIONS_BOOK"."PAGES", "ANNOTATIONS_BOOK"."RATING", "ANNOTATIONS_BOOK"."PRICE", "ANNOTATIONS_BOOK"."CONTACT_ID", "ANNOTATIONS_BOOK"."PUBLISHER_ID", "ANNOTATIONS_BOOK"."PUBDATE" FROM "ANNOTATIONS_BOOK" WHERE "ANNOTATIONS_BOOK"."ID" = %s FETCH FIRST 21 ROWS ONLY;
SELECT "ANNOTATIONS_BOOK"."ID", "ANNOTATIONS_BOOK"."ISBN", "ANNOTATIONS_BOOK"."NAME", "ANNOTATIONS_BOOK"."PAGES", "ANNOTATIONS_BOOK"."RATING", "ANNOTATIONS_BOOK"."PRICE", "ANNOTATIONS_BOOK"."CONTACT_ID", "ANNOTATIONS_BOOK"."PUBLISHER_ID", "ANNOTATIONS_BOOK"."PUBDATE" FROM "ANNOTATIONS_BOOK" WHERE "ANNOTATIONS_BOOK"."ID" = %s FETCH FIRST 21 ROWS ONLY;
SELECT "ANNOTATIONS_BOOK"."ID", "ANNOTATIONS_BOOK"."ISBN", "ANNOTATIONS_BOOK"."NAME", "ANNOTATIONS_BOOK"."PAGES", "ANNOTATIONS_BOOK"."RATING", "ANNOTATIONS_BOOK"."PRICE", "ANNOTATIONS_BOOK"."CONTACT_ID", "ANNOTATIONS_BOOK"."PUBLISHER_ID", "ANNOTATIONS_BOOK"."PUBDATE" FROM "ANNOTATIONS_BOOK" WHERE "ANNOTATIONS_BOOK"."RATING" = %s ORDER BY "ANNOTATIONS_BOOK"."ID" ASC FETCH FIRST 1 ROWS ONLY;
