SELECT "ANNOTATIONS_BOOK"."ID", "ANNOTATIONS_BOOK"."ISBN", "ANNOTATIONS_BOOK"."NAME", "ANNOTATIONS_BOOK"."PAGES", "ANNOTATIONS_BOOK"."RATING", "ANNOTATIONS_BOOK"."PRICE", "ANNOTATIONS_BOOK"."CONTACT_ID", "ANNOTATIONS_BOOK"."PUBLISHER_ID", "ANNOTATIONS_BOOK"."PUBDATE", (CAST(NULL AS DOUBLE) + "ANNOTATIONS_BOOK"."RATING") AS "ADJUSTED_RATING" FROM "ANNOTATIONS_BOOK" WHERE "ANNOTATIONS_BOOK"."ID" = %s FETCH FIRST 21 ROWS ONLY;
