SELECT "ANNOTATIONS_BOOK"."ID", "ANNOTATIONS_BOOK"."ISBN", "ANNOTATIONS_BOOK"."NAME", "ANNOTATIONS_BOOK"."PAGES", "ANNOTATIONS_BOOK"."RATING", "ANNOTATIONS_BOOK"."PRICE", "ANNOTATIONS_BOOK"."CONTACT_ID", "ANNOTATIONS_BOOK"."PUBLISHER_ID", "ANNOTATIONS_BOOK"."PUBDATE", COALESCE(CAST(%s AS INTEGER), CAST(%s AS INTEGER)) AS "IS_BOOK" FROM "ANNOTATIONS_BOOK";
SELECT "ANNOTATIONS_BOOK"."ID", "ANNOTATIONS_BOOK"."ISBN", "ANNOTATIONS_BOOK"."NAME", "ANNOTATIONS_BOOK"."PAGES", "ANNOTATIONS_BOOK"."RATING", "ANNOTATIONS_BOOK"."PRICE", "ANNOTATIONS_BOOK"."CONTACT_ID", "ANNOTATIONS_BOOK"."PUBLISHER_ID", "ANNOTATIONS_BOOK"."PUBDATE", SUM("ANNOTATIONS_BOOK"."RATING") AS "SUM_RATING" FROM "ANNOTATIONS_BOOK" GROUP BY "ANNOTATIONS_BOOK"."ID", "ANNOTATIONS_BOOK"."ISBN", "ANNOTATIONS_BOOK"."NAME", "ANNOTATIONS_BOOK"."PAGES", "ANNOTATIONS_BOOK"."RATING", "ANNOTATIONS_BOOK"."PRICE", "ANNOTATIONS_BOOK"."CONTACT_ID", "ANNOTATIONS_BOOK"."PUBLISHER_ID", "ANNOTATIONS_BOOK"."PUBDATE" HAVING SUM("ANNOTATIONS_BOOK"."RATING") = (SUM("ANNOTATIONS_BOOK"."RATING"));
SELECT "ANNOTATIONS_BOOK"."ID", "ANNOTATIONS_BOOK"."ISBN", "ANNOTATIONS_BOOK"."NAME", "ANNOTATIONS_BOOK"."PAGES", "ANNOTATIONS_BOOK"."RATING", "ANNOTATIONS_BOOK"."PRICE", "ANNOTATIONS_BOOK"."CONTACT_ID", "ANNOTATIONS_BOOK"."PUBLISHER_ID", "ANNOTATIONS_BOOK"."PUBDATE", YEAR("ANNOTATIONS_BOOK"."PUBDATE") AS "PUBDATE_YEAR" FROM "ANNOTATIONS_BOOK" ORDER BY "ANNOTATIONS_BOOK"."ID" ASC FETCH FIRST 1 ROWS ONLY;
SELECT "ANNOTATIONS_BOOK"."ID", "ANNOTATIONS_BOOK"."ISBN", "ANNOTATIONS_BOOK"."NAME", "ANNOTATIONS_BOOK"."PAGES", "ANNOTATIONS_BOOK"."RATING", "ANNOTATIONS_BOOK"."PRICE", "ANNOTATIONS_BOOK"."CONTACT_ID", "ANNOTATIONS_BOOK"."PUBLISHER_ID", "ANNOTATIONS_BOOK"."PUBDATE", YEAR("ANNOTATIONS_BOOK"."PUBDATE") AS "PUBDATE_YEAR" FROM "ANNOTATIONS_BOOK";
SELECT "ANNOTATIONS_BOOK"."ID", "ANNOTATIONS_BOOK"."ISBN", "ANNOTATIONS_BOOK"."NAME", "ANNOTATIONS_BOOK"."PAGES", "ANNOTATIONS_BOOK"."RATING", "ANNOTATIONS_BOOK"."PRICE", "ANNOTATIONS_BOOK"."CONTACT_ID", "ANNOTATIONS_BOOK"."PUBLISHER_ID", "ANNOTATIONS_BOOK"."PUBDATE", "ANNOTATIONS_AUTHOR"."AGE" AS "AUTHOR_AGE" FROM "ANNOTATIONS_BOOK" LEFT OUTER JOIN "ANNOTATIONS_BOOK_AUTHORS" ON ("ANNOTATIONS_BOOK"."ID" = "ANNOTATIONS_BOOK_AUTHORS"."BOOK_ID") LEFT OUTER JOIN "ANNOTATIONS_AUTHOR" ON ("ANNOTATIONS_BOOK_AUTHORS"."AUTHOR_ID" = "ANNOTATIONS_AUTHOR"."ID") WHERE "ANNOTATIONS_BOOK"."ID" = %s ORDER BY 10 ASC FETCH FIRST 1 ROWS ONLY;
SELECT "ANNOTATIONS_BOOK"."ID", "ANNOTATIONS_BOOK"."ISBN", "ANNOTATIONS_BOOK"."NAME", "ANNOTATIONS_BOOK"."PAGES", "ANNOTATIONS_BOOK"."RATING", "ANNOTATIONS_BOOK"."PRICE", "ANNOTATIONS_BOOK"."CONTACT_ID", "ANNOTATIONS_BOOK"."PUBLISHER_ID", "ANNOTATIONS_BOOK"."PUBDATE", "ANNOTATIONS_AUTHOR"."AGE" AS "AUTHOR_AGE" FROM "ANNOTATIONS_BOOK" LEFT OUTER JOIN "ANNOTATIONS_BOOK_AUTHORS" ON ("ANNOTATIONS_BOOK"."ID" = "ANNOTATIONS_BOOK_AUTHORS"."BOOK_ID") LEFT OUTER JOIN "ANNOTATIONS_AUTHOR" ON ("ANNOTATIONS_BOOK_AUTHORS"."AUTHOR_ID" = "ANNOTATIONS_AUTHOR"."ID") WHERE "ANNOTATIONS_BOOK"."ID" = %s ORDER BY 10 ASC OFFSET 1 ROWS FETCH FIRST 1 ROWS ONLY;
SELECT "ANNOTATIONS_BOOK"."ID", "ANNOTATIONS_BOOK"."ISBN", "ANNOTATIONS_BOOK"."NAME", "ANNOTATIONS_BOOK"."PAGES", "ANNOTATIONS_BOOK"."RATING", "ANNOTATIONS_BOOK"."PRICE", "ANNOTATIONS_BOOK"."CONTACT_ID", "ANNOTATIONS_BOOK"."PUBLISHER_ID", "ANNOTATIONS_BOOK"."PUBDATE", "ANNOTATIONS_BOOK"."RATING" AS "ANOTHER_RATING" FROM "ANNOTATIONS_BOOK" ORDER BY "ANNOTATIONS_BOOK"."ID" ASC FETCH FIRST 1 ROWS ONLY;
SELECT "ANNOTATIONS_BOOK"."ID", "ANNOTATIONS_BOOK"."ISBN", "ANNOTATIONS_BOOK"."NAME", "ANNOTATIONS_BOOK"."PAGES", "ANNOTATIONS_BOOK"."RATING", "ANNOTATIONS_BOOK"."PRICE", "ANNOTATIONS_BOOK"."CONTACT_ID", "ANNOTATIONS_BOOK"."PUBLISHER_ID", "ANNOTATIONS_BOOK"."PUBDATE", "ANNOTATIONS_BOOK"."RATING" AS "ANOTHER_RATING" FROM "ANNOTATIONS_BOOK";
SELECT "ANNOTATIONS_BOOK"."ID", "ANNOTATIONS_BOOK"."ISBN", "ANNOTATIONS_BOOK"."NAME", "ANNOTATIONS_BOOK"."PAGES", "ANNOTATIONS_BOOK"."RATING", "ANNOTATIONS_BOOK"."PRICE", "ANNOTATIONS_BOOK"."CONTACT_ID", "ANNOTATIONS_BOOK"."PUBLISHER_ID", "ANNOTATIONS_BOOK"."PUBDATE", "ANNOTATIONS_BOOK"."RATING" AS "OTHER_RATING" FROM "ANNOTATIONS_BOOK" WHERE "ANNOTATIONS_BOOK"."RATING" = %s;
SELECT "ANNOTATIONS_BOOK"."ID", "ANNOTATIONS_BOOK"."ISBN", "ANNOTATIONS_BOOK"."NAME", "ANNOTATIONS_BOOK"."PAGES", "ANNOTATIONS_BOOK"."RATING", "ANNOTATIONS_BOOK"."PRICE", "ANNOTATIONS_BOOK"."CONTACT_ID", "ANNOTATIONS_BOOK"."PUBLISHER_ID", "ANNOTATIONS_BOOK"."PUBDATE", "ANNOTATIONS_BOOK"."RATING" AS "OTHER_RATING" FROM "ANNOTATIONS_BOOK" WHERE "ANNOTATIONS_BOOK"."RATING" = ("ANNOTATIONS_BOOK"."RATING");
SELECT "ANNOTATIONS_BOOK"."ID", "ANNOTATIONS_BOOK"."ISBN", "ANNOTATIONS_BOOK"."NAME", "ANNOTATIONS_BOOK"."PAGES", "ANNOTATIONS_BOOK"."RATING", "ANNOTATIONS_BOOK"."PRICE", "ANNOTATIONS_BOOK"."CONTACT_ID", "ANNOTATIONS_BOOK"."PUBLISHER_ID", "ANNOTATIONS_BOOK"."PUBDATE", "ANNOTATIONS_PUBLISHER"."NUM_AWARDS" AS "NUM_AWARDS", "ANNOTATIONS_PUBLISHER"."ID", "ANNOTATIONS_PUBLISHER"."NAME", "ANNOTATIONS_PUBLISHER"."NUM_AWARDS" FROM "ANNOTATIONS_BOOK" INNER JOIN "ANNOTATIONS_PUBLISHER" ON ("ANNOTATIONS_BOOK"."PUBLISHER_ID" = "ANNOTATIONS_PUBLISHER"."ID") ORDER BY "ANNOTATIONS_BOOK"."ID" ASC FETCH FIRST 1 ROWS ONLY;
SELECT "ANNOTATIONS_BOOK"."ID", "ANNOTATIONS_BOOK"."ISBN", "ANNOTATIONS_BOOK"."NAME", "ANNOTATIONS_BOOK"."PAGES", "ANNOTATIONS_BOOK"."RATING", "ANNOTATIONS_BOOK"."PRICE", "ANNOTATIONS_BOOK"."CONTACT_ID", "ANNOTATIONS_BOOK"."PUBLISHER_ID", "ANNOTATIONS_BOOK"."PUBDATE", "ANNOTATIONS_PUBLISHER"."NUM_AWARDS" AS "NUM_AWARDS", "ANNOTATIONS_PUBLISHER"."ID", "ANNOTATIONS_PUBLISHER"."NAME", "ANNOTATIONS_PUBLISHER"."NUM_AWARDS" FROM "ANNOTATIONS_BOOK" INNER JOIN "ANNOTATIONS_PUBLISHER" ON ("ANNOTATIONS_BOOK"."PUBLISHER_ID" = "ANNOTATIONS_PUBLISHER"."ID");
SELECT "ANNOTATIONS_BOOK"."ID", "ANNOTATIONS_BOOK"."ISBN", "ANNOTATIONS_BOOK"."NAME", "ANNOTATIONS_BOOK"."PAGES", "ANNOTATIONS_BOOK"."RATING", "ANNOTATIONS_BOOK"."PRICE", "ANNOTATIONS_BOOK"."CONTACT_ID", "ANNOTATIONS_BOOK"."PUBLISHER_ID", "ANNOTATIONS_BOOK"."PUBDATE", "ANNOTATIONS_STORE"."NAME" AS "STORE_NAME" FROM "ANNOTATIONS_BOOK" LEFT OUTER JOIN "ANNOTATIONS_STORE_BOOKS" ON ("ANNOTATIONS_BOOK"."ID" = "ANNOTATIONS_STORE_BOOKS"."BOOK_ID") LEFT OUTER JOIN "ANNOTATIONS_STORE" ON ("ANNOTATIONS_STORE_BOOKS"."STORE_ID" = "ANNOTATIONS_STORE"."ID") WHERE "ANNOTATIONS_BOOK"."NAME" = %s ORDER BY 10 ASC;
SELECT "ANNOTATIONS_BOOK"."ID", "ANNOTATIONS_BOOK"."ISBN", "ANNOTATIONS_BOOK"."NAME", "ANNOTATIONS_BOOK"."PAGES", "ANNOTATIONS_BOOK"."RATING", "ANNOTATIONS_BOOK"."PRICE", "ANNOTATIONS_BOOK"."CONTACT_ID", "ANNOTATIONS_BOOK"."PUBLISHER_ID", "ANNOTATIONS_BOOK"."PUBDATE", "DJDB2I_GROUPING"."G1" AS "COMBINED", COUNT("ANNOTATIONS_BOOK"."RATING") AS "RATING_COUNT" FROM "ANNOTATIONS_BOOK" CROSS JOIN LATERAL (SELECT (CAST(%s AS INTEGER) * CAST(%s AS INTEGER)) AS "G1" FROM SYSIBM.SYSDUMMY1) AS "DJDB2I_GROUPING" GROUP BY "ANNOTATIONS_BOOK"."ID", "ANNOTATIONS_BOOK"."ISBN", "ANNOTATIONS_BOOK"."NAME", "ANNOTATIONS_BOOK"."PAGES", "ANNOTATIONS_BOOK"."RATING", "ANNOTATIONS_BOOK"."PRICE", "ANNOTATIONS_BOOK"."CONTACT_ID", "ANNOTATIONS_BOOK"."PUBLISHER_ID", "ANNOTATIONS_BOOK"."PUBDATE", "DJDB2I_GROUPING"."G1" ORDER BY "ANNOTATIONS_BOOK"."ID" ASC FETCH FIRST 1 ROWS ONLY;
SELECT "ANNOTATIONS_BOOK"."ID", "ANNOTATIONS_BOOK"."ISBN", "ANNOTATIONS_BOOK"."NAME", "ANNOTATIONS_BOOK"."PAGES", "ANNOTATIONS_BOOK"."RATING", "ANNOTATIONS_BOOK"."PRICE", "ANNOTATIONS_BOOK"."CONTACT_ID", "ANNOTATIONS_BOOK"."PUBLISHER_ID", "ANNOTATIONS_BOOK"."PUBDATE", "DJDB2I_GROUPING"."G1" AS "COMBINED", COUNT("ANNOTATIONS_BOOK"."RATING") AS "RATING_COUNT" FROM "ANNOTATIONS_BOOK" CROSS JOIN LATERAL (SELECT ("ANNOTATIONS_BOOK"."PRICE" * "ANNOTATIONS_BOOK"."PAGES") AS "G1" FROM SYSIBM.SYSDUMMY1) AS "DJDB2I_GROUPING" WHERE "ANNOTATIONS_BOOK"."ISBN" = %s GROUP BY "ANNOTATIONS_BOOK"."ID", "ANNOTATIONS_BOOK"."ISBN", "ANNOTATIONS_BOOK"."NAME", "ANNOTATIONS_BOOK"."PAGES", "ANNOTATIONS_BOOK"."RATING", "ANNOTATIONS_BOOK"."PRICE", "ANNOTATIONS_BOOK"."CONTACT_ID", "ANNOTATIONS_BOOK"."PUBLISHER_ID", "ANNOTATIONS_BOOK"."PUBDATE", "DJDB2I_GROUPING"."G1" ORDER BY "ANNOTATIONS_BOOK"."ID" ASC FETCH FIRST 1 ROWS ONLY;
SELECT "ANNOTATIONS_BOOK"."ID", "ANNOTATIONS_BOOK"."ISBN", "ANNOTATIONS_BOOK"."NAME", "ANNOTATIONS_BOOK"."PAGES", "ANNOTATIONS_BOOK"."RATING", "ANNOTATIONS_BOOK"."PRICE", "ANNOTATIONS_BOOK"."CONTACT_ID", "ANNOTATIONS_BOOK"."PUBLISHER_ID", "ANNOTATIONS_BOOK"."PUBDATE", "DJDB2I_GROUPING"."G1" AS "SELECTED", COUNT("ANNOTATIONS_BOOK"."RATING") AS "RATING_COUNT" FROM "ANNOTATIONS_BOOK" CROSS JOIN LATERAL (SELECT CAST(%s AS BOOLEAN) AS "G1" FROM SYSIBM.SYSDUMMY1) AS "DJDB2I_GROUPING" WHERE "ANNOTATIONS_BOOK"."ISBN" = %s GROUP BY "ANNOTATIONS_BOOK"."ID", "ANNOTATIONS_BOOK"."ISBN", "ANNOTATIONS_BOOK"."NAME", "ANNOTATIONS_BOOK"."PAGES", "ANNOTATIONS_BOOK"."RATING", "ANNOTATIONS_BOOK"."PRICE", "ANNOTATIONS_BOOK"."CONTACT_ID", "ANNOTATIONS_BOOK"."PUBLISHER_ID", "ANNOTATIONS_BOOK"."PUBDATE", "DJDB2I_GROUPING"."G1";
SELECT "ANNOTATIONS_BOOK"."ID", "ANNOTATIONS_BOOK"."RATING" FROM "ANNOTATIONS_BOOK" WHERE "ANNOTATIONS_BOOK"."ID" = %s FETCH FIRST 21 ROWS ONLY;
SELECT "ANNOTATIONS_BOOK"."NAME" AS "NAME", crafted_alia$."ID" AS "CRAFTED_ALIA$" FROM "ANNOTATIONS_BOOK" LEFT OUTER JOIN "ANNOTATIONS_BOOK_AUTHORS" ON ("ANNOTATIONS_BOOK"."ID" = "ANNOTATIONS_BOOK_AUTHORS"."BOOK_ID") LEFT OUTER JOIN "ANNOTATIONS_AUTHOR" crafted_alia$ ON ("ANNOTATIONS_BOOK_AUTHORS"."AUTHOR_ID" = crafted_alia$."ID") ORDER BY "ANNOTATIONS_BOOK"."ID" ASC FETCH FIRST 1 ROWS ONLY;
SELECT "ANNOTATIONS_BOOK"."RATING" AS "RATING", ("ANNOTATIONS_BOOK"."RATING" - CAST(%s AS INTEGER)) AS "OTHER_RATING" FROM "ANNOTATIONS_BOOK" WHERE ("ANNOTATIONS_BOOK"."RATING" - CAST(%s AS INTEGER)) = %s FETCH FIRST 21 ROWS ONLY;
SELECT "ANNOTATIONS_BOOK"."RATING" AS "RATING", ("ANNOTATIONS_BOOK"."RATING" - CAST(%s AS INTEGER)) AS "OTHER_RATING" FROM "ANNOTATIONS_BOOK" WHERE "ANNOTATIONS_BOOK"."ID" = %s FETCH FIRST 21 ROWS ONLY;
SELECT "ANNOTATIONS_BOOK"."RATING" AS "RATING", ("ANNOTATIONS_BOOK"."RATING" - CAST(%s AS INTEGER)) AS "OTHER_RATING", "ANNOTATIONS_BOOK"."ISBN" AS "OTHER_ISBN" FROM "ANNOTATIONS_BOOK" WHERE ("ANNOTATIONS_BOOK"."RATING" - CAST(%s AS INTEGER)) = %s FETCH FIRST 21 ROWS ONLY;
SELECT "ANNOTATIONS_COMPANY"."ID", "ANNOTATIONS_COMPANY"."NAME", "ANNOTATIONS_COMPANY"."MOTTO", "ANNOTATIONS_COMPANY"."TICKER_NAME", "ANNOTATIONS_COMPANY"."DESCRIPTION", COALESCE("ANNOTATIONS_COMPANY"."MOTTO", "ANNOTATIONS_COMPANY"."TICKER_NAME", "ANNOTATIONS_COMPANY"."DESCRIPTION", CAST(%s AS NVARCHAR(32))) AS "TAGLINE" FROM "ANNOTATIONS_COMPANY" ORDER BY "ANNOTATIONS_COMPANY"."NAME" ASC;
SELECT "ANNOTATIONS_COMPANY"."NAME" AS "NAME", CHARACTER_LENGTH(TRIM("ANNOTATIONS_COMPANY"."NAME")) AS "LENGTH" FROM "ANNOTATIONS_COMPANY";
SELECT "ANNOTATIONS_EMPLOYEE"."ID", "ANNOTATIONS_EMPLOYEE"."AGE" FROM "ANNOTATIONS_EMPLOYEE" WHERE "ANNOTATIONS_EMPLOYEE"."ID" = %s FETCH FIRST 21 ROWS ONLY;
SELECT "ANNOTATIONS_EMPLOYEE"."ID", "ANNOTATIONS_EMPLOYEE"."AGE" FROM "ANNOTATIONS_EMPLOYEE" WHERE "ANNOTATIONS_EMPLOYEE"."ID" = %s FETCH FIRST 21 ROWS ONLY;
SELECT "ANNOTATIONS_EMPLOYEE"."ID", "ANNOTATIONS_EMPLOYEE"."FIRST_NAME", "ANNOTATIONS_EMPLOYEE"."MANAGER", "ANNOTATIONS_EMPLOYEE"."LAST_NAME", "ANNOTATIONS_EMPLOYEE"."STORE_ID", "ANNOTATIONS_EMPLOYEE"."AGE", "ANNOTATIONS_EMPLOYEE"."SALARY", ("ANNOTATIONS_EMPLOYEE"."SALARY" / CAST(%s AS INTEGER)) AS "NEW_SALARY" FROM "ANNOTATIONS_EMPLOYEE" FETCH FIRST 21 ROWS ONLY;
SELECT "ANNOTATIONS_EMPLOYEE"."ID", "ANNOTATIONS_EMPLOYEE"."FIRST_NAME", "ANNOTATIONS_EMPLOYEE"."MANAGER", "ANNOTATIONS_EMPLOYEE"."LAST_NAME", "ANNOTATIONS_EMPLOYEE"."STORE_ID", "ANNOTATIONS_EMPLOYEE"."AGE", "ANNOTATIONS_EMPLOYEE"."SALARY", YEAR("ANNOTATIONS_STORE"."ORIGINAL_OPENING") AS "STORE_OPENED_YEAR" FROM "ANNOTATIONS_EMPLOYEE" INNER JOIN "ANNOTATIONS_STORE" ON ("ANNOTATIONS_EMPLOYEE"."STORE_ID" = "ANNOTATIONS_STORE"."ID");
SELECT "ANNOTATIONS_PUBLISHER"."ID" AS "ID", "ANNOTATIONS_BOOK"."RATING" AS "BOOK__RATING", SUM("ANNOTATIONS_BOOK"."RATING") AS "TOTAL" FROM "ANNOTATIONS_PUBLISHER" LEFT OUTER JOIN "ANNOTATIONS_BOOK" ON ("ANNOTATIONS_PUBLISHER"."ID" = "ANNOTATIONS_BOOK"."PUBLISHER_ID") WHERE "ANNOTATIONS_PUBLISHER"."ID" = %s GROUP BY "ANNOTATIONS_PUBLISHER"."ID", "ANNOTATIONS_BOOK"."RATING";
SELECT "ANNOTATIONS_PUBLISHER"."ID", "ANNOTATIONS_PUBLISHER"."NAME", "ANNOTATIONS_PUBLISHER"."NUM_AWARDS" FROM "ANNOTATIONS_PUBLISHER" WHERE "ANNOTATIONS_PUBLISHER"."ID" IN (SELECT U0."ID" FROM "ANNOTATIONS_PUBLISHER" U0 WHERE U0."NUM_AWARDS" > %s);
SELECT "ANNOTATIONS_PUBLISHER"."NAME" AS "NAME" FROM "ANNOTATIONS_PUBLISHER" INNER JOIN "ANNOTATIONS_BOOK" ON ("ANNOTATIONS_PUBLISHER"."ID" = "ANNOTATIONS_BOOK"."PUBLISHER_ID") WHERE "ANNOTATIONS_BOOK"."ID" IN (SELECT U0."ID" FROM "ANNOTATIONS_BOOK" U0 WHERE U0."PAGES" > %s);
SELECT "ANNOTATIONS_PUBLISHER"."NAME" AS "NAME" FROM "ANNOTATIONS_PUBLISHER" LEFT OUTER JOIN "ANNOTATIONS_BOOK" ON ("ANNOTATIONS_PUBLISHER"."ID" = "ANNOTATIONS_BOOK"."PUBLISHER_ID") GROUP BY "ANNOTATIONS_PUBLISHER"."ID", "ANNOTATIONS_PUBLISHER"."NAME", "ANNOTATIONS_PUBLISHER"."NUM_AWARDS" HAVING COUNT("ANNOTATIONS_BOOK"."ID") = (SELECT COUNT(U0."ID") AS "COUNT" FROM "ANNOTATIONS_BOOK" U0 WHERE (U0."PAGES" > %s AND U0."PUBLISHER_ID" = ("ANNOTATIONS_PUBLISHER"."ID")) GROUP BY U0."PUBLISHER_ID" FETCH FIRST 1 ROWS ONLY);
SELECT "ANNOTATIONS_PUBLISHER"."NAME" AS "NAME", SUM((CAST(%s AS INTEGER) * "ANNOTATIONS_PUBLISHER"."NUM_AWARDS")) AS "MULTIPLIED_VALUE_SUM" FROM "ANNOTATIONS_PUBLISHER" GROUP BY "ANNOTATIONS_PUBLISHER"."NAME";
SELECT "ANNOTATIONS_STORE"."ID", "ANNOTATIONS_STORE"."NAME", "ANNOTATIONS_STORE"."ORIGINAL_OPENING", "ANNOTATIONS_STORE"."FRIDAY_NIGHT_CLOSING", "ANNOTATIONS_STORE"."SURFACE" FROM "ANNOTATIONS_STORE" ORDER BY "ANNOTATIONS_STORE"."ID" ASC FETCH FIRST 1 ROWS ONLY;
SELECT "ANNOTATIONS_STORE"."ID", "ANNOTATIONS_STORE"."NAME", "ANNOTATIONS_STORE"."ORIGINAL_OPENING", "ANNOTATIONS_STORE"."FRIDAY_NIGHT_CLOSING", "ANNOTATIONS_STORE"."SURFACE" FROM "ANNOTATIONS_STORE" WHERE "ANNOTATIONS_STORE"."ID" = %s FETCH FIRST 21 ROWS ONLY;
SELECT "ANNOTATIONS_STORE"."ID", "ANNOTATIONS_STORE"."NAME", "ANNOTATIONS_STORE"."ORIGINAL_OPENING", "ANNOTATIONS_STORE"."FRIDAY_NIGHT_CLOSING", "ANNOTATIONS_STORE"."SURFACE" FROM "ANNOTATIONS_STORE" WHERE "ANNOTATIONS_STORE"."ID" = %s FETCH FIRST 21 ROWS ONLY;
SELECT "ANNOTATIONS_STORE"."ID", "ANNOTATIONS_STORE"."NAME", "ANNOTATIONS_STORE"."ORIGINAL_OPENING", "ANNOTATIONS_STORE"."FRIDAY_NIGHT_CLOSING", "ANNOTATIONS_STORE"."SURFACE" FROM "ANNOTATIONS_STORE" WHERE "ANNOTATIONS_STORE"."ID" = %s FETCH FIRST 21 ROWS ONLY;
SELECT "ANNOTATIONS_STORE"."ID", "ANNOTATIONS_STORE"."NAME", "ANNOTATIONS_STORE"."ORIGINAL_OPENING", "ANNOTATIONS_STORE"."FRIDAY_NIGHT_CLOSING", "ANNOTATIONS_STORE"."SURFACE", "ANNOTATIONS_DEPARTMENTSTORE"."STORE_PTR_ID", "ANNOTATIONS_DEPARTMENTSTORE"."CHAIN", "ANNOTATIONS_STORE"."NAME" AS "OTHER_NAME", "ANNOTATIONS_DEPARTMENTSTORE"."CHAIN" AS "OTHER_CHAIN", CAST(%s AS BOOLEAN) AS "IS_OPEN", "ANNOTATIONS_BOOK"."ISBN" AS "BOOK_ISBN" FROM "ANNOTATIONS_DEPARTMENTSTORE" INNER JOIN "ANNOTATIONS_STORE" ON ("ANNOTATIONS_DEPARTMENTSTORE"."STORE_PTR_ID" = "ANNOTATIONS_STORE"."ID") LEFT OUTER JOIN "ANNOTATIONS_STORE_BOOKS" ON ("ANNOTATIONS_STORE"."ID" = "ANNOTATIONS_STORE_BOOKS"."STORE_ID") LEFT OUTER JOIN "ANNOTATIONS_BOOK" ON ("ANNOTATIONS_STORE_BOOKS"."BOOK_ID" = "ANNOTATIONS_BOOK"."ID") WHERE "ANNOTATIONS_DEPARTMENTSTORE"."CHAIN" = %s ORDER BY 11 ASC;
SELECT "ANNOTATIONS_TICKET"."ID", "ANNOTATIONS_TICKET"."ACTIVE_AT", "ANNOTATIONS_TICKET"."DURATION", ("ANNOTATIONS_TICKET"."ACTIVE_AT" + INTEGER(("ANNOTATIONS_TICKET"."DURATION") / 86400000000) DAYS + MOD(("ANNOTATIONS_TICKET"."DURATION"), 86400000000) MICROSECONDS) AS "EXPIRES" FROM "ANNOTATIONS_TICKET" ORDER BY "ANNOTATIONS_TICKET"."ID" ASC FETCH FIRST 1 ROWS ONLY;
SELECT "DJDB2I_GROUPING"."G1" AS "UNDER_40", COUNT("ANNOTATIONS_AUTHOR"."ID") AS "COUNT_ID" FROM "ANNOTATIONS_AUTHOR" CROSS JOIN LATERAL (SELECT CASE WHEN "ANNOTATIONS_AUTHOR"."AGE" < %s THEN TRUE WHEN NOT ("ANNOTATIONS_AUTHOR"."AGE" < %s) THEN FALSE END AS "G1" FROM SYSIBM.SYSDUMMY1) AS "DJDB2I_GROUPING" GROUP BY "DJDB2I_GROUPING"."G1";
